UPDATE public.pairings p SET tests=ARRAY['scale','transformation'],hypothesis='Within-lane contrast on scale, transformation.' FROM public.songs a,public.songs b WHERE p.song_a_id=a.id AND p.song_b_id=b.id AND a.title='B.O.B. (Bombs Over Baghdad)' AND b.title='Paid in Full' AND a.scoring_version='hip_hop_expansion_2026_11_10' AND b.scoring_version='hip_hop_expansion_2026_11_10' AND p.active=false;